using Payments;

namespace PaymentGateway.Tests;

/// <summary>
/// Stub implementation of <see cref="IPaymentProvider"/> for unit testing.
/// </summary>
internal sealed class FakePaymentProvider : IPaymentProvider
{
    public ChargeResult? ChargeResultToReturn { get; set; }
    public RefundResult? RefundResultToReturn { get; set; }
    public Exception? ExceptionToThrow { get; set; }

    public string? LastCardToken { get; private set; }
    public decimal LastAmount { get; private set; }
    public string? LastChargeId { get; private set; }

    public Task<ChargeResult> ProcessChargeAsync(string cardToken, decimal amount)
    {
        if (ExceptionToThrow is not null)
            throw ExceptionToThrow;

        LastCardToken = cardToken;
        LastAmount = amount;
        return Task.FromResult(ChargeResultToReturn
            ?? new ChargeResult("ch_default", true));
    }

    public Task<RefundResult> ProcessRefundAsync(string chargeId)
    {
        if (ExceptionToThrow is not null)
            throw ExceptionToThrow;

        LastChargeId = chargeId;
        return Task.FromResult(RefundResultToReturn
            ?? new RefundResult("rf_default", true));
    }
}

using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProvider _provider;
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new Payments.PaymentGateway(_provider);
    }

    #region Constructor

    [TestMethod]
    public void Constructor_NullProvider_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => new Payments.PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    #endregion

    #region ChargeAsync — validation

    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(null!, 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyCardToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("", 10m));
    }

    [TestMethod]
    public async Task ChargeAsync_WhitespaceCardToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("   ", 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_AmountExceedsMaximum_ThrowsArgumentOutOfRangeException()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", 1_000_000m));
        Assert.AreEqual("amount", ex.ParamName);
    }

    #endregion

    #region ChargeAsync — happy path

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessResult()
    {
        _provider.ChargeResultToReturn = new ChargeResult("ch_123", true);

        var result = await _gateway.ChargeAsync("tok_abc", 49.99m);

        Assert.AreEqual("ch_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_PassesParametersToProvider()
    {
        await _gateway.ChargeAsync("tok_xyz", 75.00m);

        Assert.AreEqual("tok_xyz", _provider.LastCardToken);
        Assert.AreEqual(75.00m, _provider.LastAmount);
    }

    [TestMethod]
    [DataRow(0.01, DisplayName = "Minimum charge")]
    [DataRow(999_999.99, DisplayName = "Maximum charge")]
    [DataRow(100.00, DisplayName = "Typical charge")]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    #endregion

    #region ChargeAsync — provider failure

    [TestMethod]
    public async Task ChargeAsync_ProviderReturnsFailure_ReturnsFailureResult()
    {
        _provider.ChargeResultToReturn = new ChargeResult("ch_fail", false);

        var result = await _gateway.ChargeAsync("tok_abc", 10m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual("ch_fail", result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Provider down");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.ChargeAsync("tok_abc", 10m));
    }

    #endregion

    #region RefundAsync — validation

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(""));
    }

    [TestMethod]
    public async Task RefundAsync_WhitespaceChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync("   "));
    }

    #endregion

    #region RefundAsync — happy path

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        _provider.RefundResultToReturn = new RefundResult("rf_456", true);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.AreEqual("rf_456", result.RefundId);
        Assert.IsTrue(result.Success);
